package ru.truetv.launcher;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.Typeface;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Discover exported system Settings routes, test, then save the exact public Intent. */
public final class BluetoothScreens extends Activity {
    private String appearance;
    private static final String SAVED="bluetooth_route";
    private static final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final ArrayList<Route> all=new ArrayList<>(),shown=new ArrayList<>();private EditText search;private Button mode;private ListView list;private TextView count;private boolean full,loading=true,left;private String pending;private int first;private final Handler main=new Handler(Looper.getMainLooper());
    static final class Route {final String title,key;final Intent intent;final int score;Route(String title,Intent i,int score){this.title=title;intent=i;key=i.toUri(0);this.score=score;}String search(){return title+" "+intent.getComponent()+" "+intent.getAction();}}
    public static void openSavedOrChoose(Activity a){String uri=new SettingsStore(a).text(SAVED,"");try{if(!uri.isEmpty()){Intent i=Intent.parseUri(uri,0);if(valid(a,i)&&Ui.launch(a,i))return;}}catch(Exception ignored){}a.startActivity(new Intent(a,BluetoothScreens.class));}
    public static void controls(Activity a){ActionSheet.show(a,"Bluetooth",
        new ActionSheet.Item(Ui.word(a,"Выбрать экран Bluetooth","Choose Bluetooth screen"),"bluetooth",()->a.startActivity(new Intent(a,BluetoothScreens.class))),
        new ActionSheet.Item(Ui.word(a,"Все экраны настроек","All Settings screens"),"settings",()->a.startActivity(new Intent(a,BluetoothScreens.class).putExtra("all",true))),
        new ActionSheet.Item(Ui.word(a,"Сбросить сохранённый переход","Reset saved route"),"reset",()->new SettingsStore(a).data.edit().remove(SAVED).apply()));}
    static boolean valid(Context c,Intent i){try{if(i.getComponent()==null)return false;ActivityInfo a=c.getPackageManager().getActivityInfo(i.getComponent(),0);return accessible(c,a);}catch(Exception e){return false;}}
    private static boolean accessible(Context c,ActivityInfo a){return a.enabled&&a.applicationInfo.enabled&&a.exported&&(a.applicationInfo.flags&ApplicationInfo.FLAG_SYSTEM)!=0&&(a.permission==null||c.checkCallingOrSelfPermission(a.permission)==PackageManager.PERMISSION_GRANTED);}
    protected void onCreate(Bundle state){appearance=Ui.prepare(this);super.onCreate(state);Ui.bars(this);full=state!=null?state.getBoolean("all"):getIntent().getBooleanExtra("all",false);pending=state==null?null:state.getString("pending");left=state!=null&&state.getBoolean("left");
        LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(Ui.dp(this,24),Ui.dp(this,16),Ui.dp(this,24),Ui.dp(this,16));Ui.backdrop(this,root);setContentView(root);
        TextView title=Ui.label(this,Ui.word(this,"Экран Bluetooth","Bluetooth screen"),22);root.addView(title);
        LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);search=new EditText(this);search.setSingleLine();search.setTextColor(Ui.ink(BluetoothScreens.this));search.setTextSize(18);search.setHintTextColor(Ui.muted(this));search.setHint(Ui.word(this,"Поиск: Bluetooth, пульт, accessories…","Search: Bluetooth, remote, accessories…"));bar.addView(search,new LinearLayout.LayoutParams(0,Ui.dp(this,52),1));mode=new Button(this);bar.addView(mode,new LinearLayout.LayoutParams(-2,Ui.dp(this,52)));root.addView(bar);count=Ui.label(this,"…",13);root.addView(count);
        list=new ListView(this);list.setCacheColorHint(android.graphics.Color.TRANSPARENT);list.setDividerHeight(Ui.dp(this,1));list.setAdapter(new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}public View getView(int p,View reuse,ViewGroup parent){TextView row=reuse instanceof TextView?(TextView)reuse:Ui.label(BluetoothScreens.this,"",16);Route r=shown.get(p);boolean saved=r.key.equals(new SettingsStore(BluetoothScreens.this).text(SAVED,""));row.setText(r.title+"\n"+r.intent.getComponent().getClassName()+(r.intent.getAction()==null?"":"\n"+r.intent.getAction()));row.setTextColor(saved?Ui.accent(BluetoothScreens.this):Ui.ink(BluetoothScreens.this));row.setTypeface(null,saved?Typeface.BOLD:Typeface.NORMAL);row.setPadding(Ui.dp(BluetoothScreens.this,12),Ui.dp(BluetoothScreens.this,10),Ui.dp(BluetoothScreens.this,12),Ui.dp(BluetoothScreens.this,10));row.setMinHeight(Ui.dp(BluetoothScreens.this,60));return row;}});root.addView(list,new LinearLayout.LayoutParams(-1,0,1));
        Button close=new Button(this);close.setText(Ui.word(this,"Закрыть","Close"));close.setOnClickListener(v->finish());root.addView(close);mode.setOnClickListener(v->{full=!full;filter();});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int n,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){filter();}public void afterTextChanged(Editable e){}});list.setOnItemClickListener((parent,v,p,id)->{Route r=shown.get(p);first=list.getFirstVisiblePosition();if(valid(this,r.intent)&&Ui.launch(this,r.intent)){pending=r.key;left=false;}else Ui.toast(this,"Этот экран недоступен. Выберите другой.","This screen is unavailable. Choose another.");});if(state!=null){search.setText(state.getString("query",""));first=state.getInt("first");}
        getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);worker.execute(()->{ArrayList<Route> routes=discover(this);main.post(()->{if(isFinishing()||isDestroyed())return;all.addAll(routes);loading=false;filter();list.setSelection(first);});});filter();}
    private static ArrayList<Route> discover(Context c){PackageManager pm=c.getPackageManager();LinkedHashMap<String,Route> unique=new LinkedHashMap<>();String[] actions={"com.google.android.intent.action.CONNECT_INPUT","android.settings.BLUETOOTH_SETTINGS","android.settings.BLUETOOTH_PAIRING_SETTINGS","android.settings.CONNECTED_DEVICE_SETTINGS","android.bluetooth.devicepicker.action.LAUNCH"};for(String action:actions)try{for(ResolveInfo r:pm.queryIntentActivities(new Intent(action),0)){Intent i=new Intent(action).setComponent(new ComponentName(r.activityInfo.packageName,r.activityInfo.name));if(accessible(c,r.activityInfo)){Route route=new Route(String.valueOf(r.loadLabel(pm)),i,120);unique.put(route.key,route);}}}catch(RuntimeException ignored){}
        for(ApplicationInfo app:pm.getInstalledApplications(0)){if((app.flags&ApplicationInfo.FLAG_SYSTEM)==0)continue;String pkg=app.packageName.toLowerCase(Locale.ROOT);if(!pkg.contains("setting")&&!pkg.contains("bluetooth")&&!pkg.contains("accessor"))continue;try{PackageInfo info=pm.getPackageInfo(app.packageName,PackageManager.GET_ACTIVITIES);if(info.activities==null)continue;for(ActivityInfo activity:info.activities){Intent i=new Intent().setComponent(new ComponentName(app.packageName,activity.name));if(!accessible(c,activity))continue;String title=String.valueOf(activity.loadLabel(pm));String name=Choices.searchable(activity.name+" "+title);int score=name.contains("addaccessory")?100:name.contains("bluetooth")||name.contains("блютуз")?90:name.contains("accessor")||name.contains("remote")||name.contains("пульт")||name.contains("аксессуар")?70:name.contains("connect")||name.contains("pair")||name.contains("подключ")?40:0;Route route=new Route(title,i,score);unique.put(route.key,route);}}catch(Exception ignored){}}
        ArrayList<Route> result=new ArrayList<>(unique.values());Collections.sort(result,(a,b)->a.score==b.score?a.search().compareToIgnoreCase(b.search()):Integer.compare(b.score,a.score));return result;}
    private void filter(){if(list==null)return;shown.clear();String q=search.getText().toString();for(Route r:all)if((full||r.score>0)&&Choices.matches(r.search(),q))shown.add(r);((BaseAdapter)list.getAdapter()).notifyDataSetChanged();mode.setText(Ui.word(this,full?"Рекомендации":"Показать всё",full?"Recommended":"Show all"));count.setText(loading?Ui.word(this,"Поиск экранов…","Finding screens…"):Ui.word(this,"Найдено: ","Found: ")+shown.size());}
    protected void onPause(){super.onPause();if(pending!=null)left=true;}
    protected void onResume(){super.onResume();if(!Ui.appearance(this).equals(appearance)){recreate();return;}Ui.bars(this);if(pending!=null&&left){final String candidate=pending;pending=null;left=false;ActionSheet.show(this,Ui.word(this,"Открылся нужный экран?","Did the correct screen open?"),
        new ActionSheet.Item(Ui.word(this,"Сохранить переход Bluetooth","Save Bluetooth route"),"bluetooth",()->{new SettingsStore(this).data.edit().putString(SAVED,candidate).apply();filter();finish();}),
        new ActionSheet.Item(Ui.word(this,"Выбрать другой","Choose another"),"replace",()->{filter();list.setSelection(first);list.requestFocus();}));}}
    protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("all",full);state.putString("query",search.getText().toString());state.putString("pending",pending);state.putBoolean("left",left);state.putInt("first",first);}
}
